/* example.c: Example C source file for ingest lab testing. */
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

/* compute_score: returns a quality score between 0 and 100. */
int compute_score(const char *text, int len)
{
   if (!text || len <= 0)
      return 0;
   int score = 0;
   for (int i = 0; i < len; i++)
      if (text[i] != ' ')
         score++;
   return (score * 100) / len;
}

/* normalize_text: strips leading/trailing whitespace in place. */
void normalize_text(char *buf, int *len)
{
   if (!buf || !len || *len == 0)
      return;
   int start = 0;
   while (start < *len && buf[start] == ' ')
      start++;
   int end = *len - 1;
   while (end > start && buf[end] == ' ')
      end--;
   *len = end - start + 1;
   memmove(buf, buf + start, (size_t)*len);
   buf[*len] = '\0';
}

int main(void)
{
   char test[] = "  hello world  ";
   int len = (int)strlen(test);
   normalize_text(test, &len);
   printf("score=%d\n", compute_score(test, len));
   return 0;
}
